(line: Message): CellHandler => {
  const m = line.content.match(/^(\S+)/);
  return { text: m ? m[1] : "-" };
}

(line: Message): CellHandler => {
  const m = line.content.match(/^\S+\s+(\S+)/);
  return { text: m ? m[1] : "-" };
}

(line: Message): CellHandler => {
  const m = line.content.match(/^\S+\s+\S+\s+([^\s:]+):\s*/);
  return { text: m ? m[1] : "" };
}

(line: Message): CellHandler => {
  const m = line.content.match(/^\S+\s+\S+\s+(?:[^\s:]+:\s*)?(.*)$/);
  return { text: m ? m[1] : line.content };
}
